  }
  await gotoLoop(bot, new goals.GoalNear(fwd0.x, fwd0.y, fwd0.z, 0), { timeoutMs: 8000, maxAttempts: 2 }, ctx).catch((err) => {
    ctx.log?.('warn', `branchMine: corridor step failed: ${err.message}`);
