cat > cave/_tmp_zonefilter_test.mjs << 'EOF'
import fs from 'node:fs';
const parsed = JSON.parse(fs.readFileSync('cave/zones.json', 'utf8'));
const zones = parsed.zones.map((z) => ({
  name: z.name,
  x1: Math.min(z.box.x1, z.box.x2), x2: Math.max(z.box.x1, z.box.x2),
  y1: Math.min(z.box.y1, z.box.y2), y2: Math.max(z.box.y1, z.box.y2),
  z1: Math.min(z.box.z1, z.box.z2), z2: Math.max(z.box.z1, z.box.z2),
}));

function isInDigZone(pos, zoneList) {
  if (zoneList.length === 0) return true;
  return zoneList.some((z) => pos.x >= z.x1 && pos.x <= z.x2 && pos.y >= z.y1 && pos.y <= z.y2 && pos.z >= z.z1 && pos.z <= z.z2);
}

function resolveZones(allZones, zoneName) {
  if (!zoneName) return allZones;
  const named = allZones.filter((z) => z.name === zoneName);
  if (named.length === 0) throw new Error(`mineBlocks: no zone named "${zoneName}" in zones.json (check spelling/case)`);
  return named;
}

// Thak's exact incident candidate: copper_ore at (21,87,57), inside
// mine_stair, NOT inside mine_field (Thak's assigned workstation zone).
const candidate = { x: 21, y: 87, z: 57 };

console.log('unfiltered (old behavior, no zone param):', isInDigZone(candidate, resolveZones(zones, undefined)), '(expect true — mine_stair passes, this IS the bug)');
console.log('filtered to zone:"mine_field" (Thak\'s assigned zone):', isInDigZone(candidate, resolveZones(zones, 'mine_field')), '(expect false — correctly rejected)');

// Sanity: a genuine mine_field candidate still passes
const goodCandidate = { x: 25, y: 88, z: 70 };
console.log('genuine mine_field candidate (25,88,70), filtered:', isInDigZone(goodCandidate, resolveZones(zones, 'mine_field')), '(expect true)');

// Unknown zone name -> clear error, not silent fail-open
try {
  resolveZones(zones, 'mine_typo');
  console.log('FAIL: should have thrown for unknown zone name');
} catch (err) {
  console.log('unknown zone name correctly throws:', err.message);
}

// No zone param at all -> fully unchanged old behavior for a genuine mine_field candidate too
console.log('unfiltered, genuine mine_field candidate still works:', isInDigZone(goodCandidate, resolveZones(zones, undefined)), '(expect true, no regression)');
EOF
node cave/_tmp_zonefilter_test.mjs
