    try {
      await rawWalkTo(bot, goal, finalCheck.range, ctx);
      return;
    } catch (rawErr) {
      lastErr = rawErr;
    }
  }

  throw new Error(`gotoLoopPf: failed after ${maxAttempts} attempts: ${lastErr?.message ?? 'unknown error'}`);
