  buf.writeInt32LE(id, 4);
  buf.writeInt32LE(type, 8);
  body.copy(buf, 12);
  buf.writeInt8(0, 12 + body.length);
  buf.writeInt8(0, 12 + body.length + 1);
  return buf;
}

export function createRconChat(cfg) {
  const { host, port, password } = loadRconConfig(cfg);
  let socket = null;
  let authed = false;

209 cave/rconchat.js
  // Name keeps its [CAVE] tag + team color (user decree) — only the message
  // body goes grey.
  function sayStatus(botName, teamColor, text) {
    return tellraw([
      { text: '<', color: 'dark_gray' },
      { text: `[CAVE] ${botName}`, color: teamColor || 'white' },
      { text: '> ', color: 'dark_gray' },
      { text: String(text), color: 'gray' },
    ]);
  }

  function sayFancy(botName, teamColor, text, color = 'gold') {
    return tellraw([
      { text: '<', color: 'dark_gray' },
      { text: `[CAVE] ${botName}`, color: teamColor },
      { text: '> ', color: 'dark_gray' },
      { text: String(text), color },
    ]);
  }

  // Diplomacy voice: words cycle rainbow colors. Name keeps tag + team color.
  const RAINBOW = ['red', 'gold', 'yellow', 'green', 'aqua', 'blue', 'light_purple'];
  function sayRainbow(botName, teamColor, text) {
    const parts = String(text).split(' ').map((word, i) => ({
      text: word + ' ',
      color: RAINBOW[i % RAINBOW.length],
    }));
    return tellraw([
      { text: '<', color: 'dark_gray' },
      { text: `[CAVE] ${botName}`, color: teamColor },
      { text: '> ', color: 'dark_gray' },
      ...parts,
    ]);
  }

  function close() {
    failAllPending(new Error('rcon closed'));
    return new Promise((resolve) => {
      if (!socket) return resolve();
      socket.end(() => resolve());
    });
  }

  return { send, sayStatus, sayFancy, sayRainbow, close };
}

